// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

const N = 8, gapSum = 8;
let gapsPossibilities = [];
let u, margin = 75;

const N_FRAMES = 50;
let truchetTiles = [];
let prevHorizGaps, prevVertGaps;
let horizGaps, vertGaps;

function setup() {
  createCanvas(500, 500, WEBGL);
  noStroke();

  getGapsPossibilities();

  u = (width-2*margin)/(N+gapSum);

  for (let i = 0; i < N; i++) {
    let newLine = [];
    for (let j = 0; j < N; j++) {
      newLine.push(random() < 1/2 ? 0 : 1);
    }
    truchetTiles.push(newLine);
  }

  prevHorizGaps = generateGaps();
  prevVertGaps = generateGaps();
  horizGaps = generateGaps();
  vertGaps = generateGaps();
}

function draw() {
  let colors = ["#1a1c37", "#ffccd1"];
  background(colors[0]);
  translate(-width/2, -height/2);

  let t = (frameCount%N_FRAMES)/N_FRAMES;
  t = easeInOutExpo(t);

  if ((frameCount) % N_FRAMES == 0) {
    prevHorizGaps = horizGaps;
    prevVertGaps = vertGaps;
    horizGaps = generateGaps();
    vertGaps = generateGaps();
  }

  let y = margin;
  for (let j = 0; j < N; j++) {
    let x = margin;
    let h = j < N-1 ? u*lerp(prevVertGaps[j], vertGaps[j], t) : 0;
    for (let i = 0; i < N; i++) {
      // truchet tile
      fill(colors[truchetTiles[i][j]]);
      rect(x, y, u, u);

      fill(colors[0]);
      circle(x+u, y, u);
      circle(x, y+u, u);

      fill(colors[1]);
      circle(x, y, u);
      circle(x+u, y+u, u);

      // rectangles beneath
      fill(colors[0]);
      rect(x, y+u, u, h);
      if (i == 0) rect(x-u/2, y+u, u, h);
      //if (i == 0 && j < N-1) rect(0, y+u/2, margin, h+u);

      fill(colors[1]);
      rect(x+u/2, y+u, u/2, h);
      if (i == N-1) rect(x+u, y+u, u/2, h);
      //if (i == N-1 && j < N-1) rect(x+u, y+u/2, margin, h+u);

      x += u;

      if (i < N-1) {
        // rectangles to the right
        let w = u*lerp(prevHorizGaps[i], horizGaps[i], t);

        fill(colors[0]);
        rect(x, y, w, u/2);
        if (j == 0) rect(x, y-u/2, w, u/2);
        //if (j == 0) rect(x-u/2, 0, w+u, margin);

        fill(colors[1]);
        rect(x, y+u/2, w, u/2+h);
        if (j == N-1) rect(x, y+u, w, u/2+h);
        //if (j == N-1) rect(x-u/2, y+u, w+h+u, margin);

        x += w;
      }

      colors = [colors[1], colors[0]];
    }
    y += u+h;
    if (N % 2 == 0) colors = [colors[1], colors[0]];
  }
}

// naive algorithm for the subset sum problem, where sets need to be of length N
function getGapsPossibilities(arr = []) {
  if (arr.length == N-1) {
    let sum = 0;
    for (let a of arr) sum += a;
    if (sum == gapSum) gapsPossibilities.push(arr);
    return;
  }
  for (let i = 0; i <= N; i++) {
    getGapsPossibilities([...arr, i]);
  }
}

function generateGaps() {
  return shuffle(random(gapsPossibilities));
}

// from https://easings.net/
function easeInOutExpo(x) {
  return x === 0
    ? 0
    : x === 1
    ? 1
    : x < 0.5 ? Math.pow(2, 20 * x - 10) / 2
    : (2 - Math.pow(2, -20 * x + 10)) / 2;
}
